	public Task<FinancePayablesConfiguration?> GetConfigurationAsync(CancellationToken cancellationToken = default) =>
		Database.QuerySingleOrDefaultAsync("SELECT Id,Version,LegalEntityId,FiscalCalendarId,InvoicePostingProfileId,CreditNotePostingProfileId,PaymentPostingProfileId,IsActive FROM FinancePayablesConfigurations ORDER BY Id;", ReadConfiguration, cancellationToken);

	public Task<PageResult<FinanceSupplierDocument>> SearchDocumentsAsync(string? searchText, FinancePayableDocumentStatus? status, int pageNumber, int pageSize, CancellationToken cancellationToken = default)
	{
		var filters = new List<string> { "1=1" };
		var parameters = new List<DatabaseParameter>();
		if (status.HasValue) { filters.Add("d.Status=$Status"); parameters.Add(Parameter("$Status", (int)status.Value)); }
		if (!string.IsNullOrWhiteSpace(searchText))
		{
			filters.Add("(s.Name LIKE $Search OR d.SupplierDocumentNumber LIKE $Search OR d.InternalReference LIKE $Search)");
			parameters.Add(Parameter("$Search", $"%{searchText.Trim()}%"));
		}
		var from = "FROM FinanceSupplierDocuments d INNER JOIN Suppliers s ON s.Id=d.SupplierId";
		var where = $"WHERE {string.Join(" AND ", filters)}";
		return Database.QueryPageAsync($"SELECT {DocumentColumns} {from} {where} ORDER BY d.DocumentDate DESC,d.Id DESC", $"SELECT COUNT(*) {from} {where};", ReadDocument, pageNumber, pageSize, cancellationToken, parameters.ToArray());
	}

	public async Task<FinanceSupplierDocument?> GetDocumentAsync(long id, CancellationToken cancellationToken = default)
	{
		var document = await Database.QuerySingleOrDefaultAsync($"SELECT {DocumentColumns} FROM FinanceSupplierDocuments d INNER JOIN Suppliers s ON s.Id=d.SupplierId WHERE d.Id=$Id;", ReadDocument, cancellationToken, Parameter("$Id", id));
		return document is null ? null : document with { Lines = await LoadLinesAsync(id, cancellationToken) };
	}

	public Task<PageResult<FinancePayableOpenItem>> SearchOpenItemsAsync(string? searchText, bool includeSettled, int pageNumber, int pageSize, CancellationToken cancellationToken = default)
	{
		var filters = new List<string> { "oi.IsVoided=0" };
		var parameters = new List<DatabaseParameter>();
		if (!includeSettled) filters.Add("oi.RemainingAmount>0");
		if (!string.IsNullOrWhiteSpace(searchText))
		{
			filters.Add("(s.Name LIKE $Search OR oi.SourceReference LIKE $Search OR oi.SourceId LIKE $Search)");
			parameters.Add(Parameter("$Search", $"%{searchText.Trim()}%"));
		}
		var from = "FROM FinancePayableOpenItems oi INNER JOIN Suppliers s ON s.Id=oi.SupplierId";
		var where = $"WHERE {string.Join(" AND ", filters)}";
		return Database.QueryPageAsync($"SELECT {OpenItemColumns} {from} {where} ORDER BY oi.DueDate,oi.Id", $"SELECT COUNT(*) {from} {where};", ReadOpenItem, pageNumber, pageSize, cancellationToken, parameters.ToArray());
	}

