	public Task<IReadOnlyList<FinanceSupplierStatementRow>> GetSupplierStatementAsync(long supplierId, CurrencyCode currency, DateOnly fromDate, DateOnly toDate, CancellationToken cancellationToken = default) =>
		Database.QueryAsync("SELECT DocumentDate,Kind,COALESCE(SourceReference,SourceId),SourceType,CurrencyCode,OriginalAmount,RemainingAmount FROM FinancePayableOpenItems WHERE SupplierId=$SupplierId AND CurrencyCode=$Currency AND DocumentDate>=$FromDate AND DocumentDate<=$ToDate AND IsVoided=0 ORDER BY DocumentDate,Id;", reader =>
		{
			var kind = (FinancePayableOpenItemKind)Convert.ToInt32(reader.GetValue(1), CultureInfo.InvariantCulture);
			var amount = ReadDecimal(reader,5);
			return new FinanceSupplierStatementRow(ReadDateOnly(reader,0), kind.ToString(), reader.GetString(2), reader.GetString(3), new CurrencyCode(reader.GetString(4)), kind == FinancePayableOpenItemKind.Invoice ? 0m : amount, kind == FinancePayableOpenItemKind.Invoice ? amount : 0m, ReadDecimal(reader,6));
		}, cancellationToken, Parameter("$SupplierId", supplierId), Parameter("$Currency", currency.Value), Parameter("$FromDate", fromDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)), Parameter("$ToDate", toDate.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture)));

